from pathlib import Path

p=Path('index.html')
s=p.read_text(encoding='utf-8')
MARKER='COPAFEM_USER_LOGO_20260911'
if MARKER in s:
    print('user logo already applied')
    raise SystemExit

b64=(
''
''
''
''
'fpg76uXEAAAAAElFTkSuQmCC'
)

old='src="logo-copafem-real.png?v=20260911"'
new=f'src="data:image/png;base64,{b64}" data-logo="{MARKER}"'
if old not in s:
    raise SystemExit('No se encontró el logo actual de la portada')
s=s.replace(old,new,1)

# Un poco más grande para que el logo completo se lea bien en la portada.
s=s.replace('width:min(300px,76%);','width:min(335px,82%);',1)

p.write_text(s,encoding='utf-8')
print('Logo COPAFEM enviado por usuario aplicado a portada')
